// "Verse of the day" on the home page (settings/features.dailyVerse).
// Pure Dart: no Flutter / Firebase imports, so the logic is unit-tested.
//
// Verses are bundled in assets/verses/daily_verses.json, generated by
// tool/gen_daily_verses.py from the public-domain Arabic Van Dyck
// (Smith-Van Dyke) Bible and, for English (ADR-047), the public-domain World
// English Bible British Edition, both published by eBible.org
// (docs/CONTENT_SOURCES.md).

import 'dart:convert';

import 'cairo_time.dart';

/// Bundled verse list (also declared in pubspec.yaml).
const dailyVersesAsset = 'assets/verses/daily_verses.json';

class Verse {
  /// Arabic text, exactly as in the source.
  final String textAr;

  /// Reference with Arabic book name and Arabic-Indic digits («يوحنا ٣: ١٦»).
  final String refAr;

  /// English reference ("John 3:16"); empty when none was given.
  final String refEn;

  /// English text (ADR-047): the World English Bible for the bundled list,
  /// optional for admin verses; empty = the English site shows the Arabic.
  final String textEn;

  const Verse({required this.textAr, required this.refAr, this.refEn = '', this.textEn = ''});

  /// What a page in [english] shows (ADR-047): the English text with its
  /// reference (the English one, else the Arabic) when there is English
  /// text; otherwise the Arabic text with the Arabic reference, so an
  /// English reference never sits under Arabic text.
  ({String text, String ref, bool rtl}) display({required bool english}) {
    final en = textEn.trim();
    if (english && en.isNotEmpty) {
      return (text: capitalizeVerseStart(en), ref: refEn.trim().isNotEmpty ? refEn.trim() : refAr.trim(), rtl: false);
    }
    return (text: textAr.trim(), ref: refAr.trim(), rtl: true);
  }
}

/// The first letter of an English verse in upper case (ADR-047): a verse cut
/// from mid-sentence ("let's hold fast…", 28 of the bundled WEB verses) reads
/// as a quotation on the hero. Leading quotes / punctuation are kept; the
/// stored text (bundled asset, admin field) is not changed.
String capitalizeVerseStart(String text) =>
    text.replaceFirstMapped(RegExp(r'^([^A-Za-z]*)([a-z])'), (m) => '${m[1]}${m[2]!.toUpperCase()}');

String _str(Object? v) => v is String ? v : '';

/// Parses the bundled asset; malformed entries are skipped.
List<Verse> parseDailyVerses(String json) {
  final raw = jsonDecode(json);
  final list = raw is Map ? raw['verses'] : null;
  if (list is! List) return const [];
  return [
    for (final v in list)
      if (v is Map && v['textAr'] is String && v['refAr'] is String && (v['textAr'] as String).trim().isNotEmpty)
        Verse(
            textAr: v['textAr'] as String,
            refAr: v['refAr'] as String,
            refEn: _str(v['refEn']),
            textEn: _str(v['textEn'])),
  ];
}

/// Day of the year (1–366) of the Cairo calendar date of [instant]: changes
/// at Cairo midnight, whatever the device time zone.
int cairoDayOfYear(DateTime instant) {
  final c = CairoTime.fromInstant(instant);
  return DateTime.utc(c.year, c.month, c.day).difference(DateTime.utc(c.year)).inDays + 1;
}

/// Day of the year (1–366) of the calendar date [date] (y/m/d only).
int dayOfYear(DateTime date) =>
    DateTime.utc(date.year, date.month, date.day).difference(DateTime.utc(date.year)).inDays + 1;

/// The rotating verse for the calendar date [date] (e.g. the liturgical
/// day, which rolls at 18:00 — ADR-039).
Verse? verseForDate(List<Verse> verses, DateTime date) =>
    verses.isEmpty ? null : verses[(dayOfYear(date) - 1) % verses.length];

/// The rotating verse for the Cairo day of [instant] (day N -> entry N-1,
/// wrapping when the list is shorter than the year).
Verse? verseForDay(List<Verse> verses, DateTime instant) =>
    verses.isEmpty ? null : verses[(cairoDayOfYear(instant) - 1) % verses.length];

/// Admin options (settings/features.dailyVerse). Missing = daily rotation.
/// On/off is the public section `Sections.dailyVerse` (missing = on), so the
/// card follows the section toggles like every public feature.
class DailyVerseConfig {
  static const daily = 'daily';
  static const fixed = 'fixed';
  static const modes = [daily, fixed];
  static const maxText = 500;
  static const maxRef = 60;

  final String mode;

  /// The admin-entered verse, used when [mode] is [fixed].
  final String textAr, refAr;

  /// Optional English text and reference of the fixed verse (ADR-047).
  final String textEn, refEn;

  const DailyVerseConfig({this.mode = daily, this.textAr = '', this.refAr = '', this.textEn = '', this.refEn = ''});

  static const defaults = DailyVerseConfig();

  factory DailyVerseConfig.fromMap(Object? v) {
    if (v is! Map) return defaults;
    final mode = v['mode'];
    return DailyVerseConfig(
      mode: modes.contains(mode) ? mode as String : daily,
      textAr: v['textAr'] is String ? v['textAr'] as String : '',
      refAr: v['refAr'] is String ? v['refAr'] as String : '',
      textEn: _str(v['textEn']),
      refEn: _str(v['refEn']),
    );
  }

  /// The English keys are written only when set, so a verse without English
  /// keeps the stored shape of before ADR-047.
  Map<String, dynamic> toMap() => {
        'mode': mode,
        'textAr': textAr,
        'refAr': refAr,
        if (textEn.isNotEmpty) 'textEn': textEn,
        if (refEn.isNotEmpty) 'refEn': refEn,
      };

  bool get isDefault => mode == daily && textAr.isEmpty && refAr.isEmpty && textEn.isEmpty && refEn.isEmpty;

  DailyVerseConfig copyWith({String? mode, String? textAr, String? refAr, String? textEn, String? refEn}) =>
      DailyVerseConfig(
        mode: mode ?? this.mode,
        textAr: textAr ?? this.textAr,
        refAr: refAr ?? this.refAr,
        textEn: textEn ?? this.textEn,
        refEn: refEn ?? this.refEn,
      );

  @override
  bool operator ==(Object other) =>
      other is DailyVerseConfig &&
      other.mode == mode &&
      other.textAr == textAr &&
      other.refAr == refAr &&
      other.textEn == textEn &&
      other.refEn == refEn;

  @override
  int get hashCode => Object.hash(mode, textAr, refAr, textEn, refEn);
}

/// The verse the home page shows at [instant] (null when nothing is
/// available). A fixed verse with no text falls back to the daily rotation.
/// [day] (the liturgical day, ADR-039) picks the rotation's entry when
/// given; otherwise the Cairo civil day of [instant].
Verse? resolveDailyVerse(DailyVerseConfig config, List<Verse> verses, DateTime instant, {DateTime? day}) {
  final text = config.textAr.trim();
  if (config.mode == DailyVerseConfig.fixed && text.isNotEmpty) {
    return Verse(textAr: text, refAr: config.refAr.trim(), textEn: config.textEn.trim(), refEn: config.refEn.trim());
  }
  return day != null ? verseForDate(verses, day) : verseForDay(verses, instant);
}
